import { ConnectRouter, Code, ConnectError } from "@connectrpc/connect";
import { DocumentService } from "./gen/documents_pb";
import { s3Client } from "./s3";
import { authContextKey } from "./auth";
import { prisma } from "./prisma";

export default (router: ConnectRouter) => {
  router.service(DocumentService, {
    async exportDocument(req, context) {
      const user = context.values.get(authContextKey);
      if (!user) {
        throw new ConnectError("Unauthenticated", Code.Unauthenticated);
      }

      // Validate that user owns or has read permissions on document in database
      const docRecord = await prisma.document.findFirst({
        where: {
          id: req.documentId,
          organizationId: user.organizationId
        }
      });

      if (!docRecord) {
        throw new ConnectError("Document not found or access denied", Code.PermissionDenied);
      }

      const s3Response = await s3Client.getObject({
        Bucket: process.env.DOCUMENTS_BUCKET,
        Key: `docs/${req.documentId}.${req.exportFormat}`
      });

      const data = await s3Response.Body.transformToByteArray();
      return {
        documentId: req.documentId,
        content: data
      };
    }
  });
};
